import { officeStage } from './office-stage.js';

const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = (v = '') => String(v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const api = async (path, options = {}) => {
  const init = { ...options, headers: { 'content-type': 'application/json', ...(options.headers || {}) } };
  if (init.body && typeof init.body !== 'string') init.body = JSON.stringify(init.body);
  const res = await fetch(path, init);
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
  return data;
};

const viewInfo = {
  workspace: ['GIT WORKSPACE', '오피스 관리'],
  office: ['TODAY\'S OFFICE', '오피스'], board: ['WORKFLOW', '작업 보드'],
  history: ['ARCHIVE', '실행 기록'], agents: ['YOUR TEAM', '에이전트'],
  schedules: ['AUTOMATION', '예약 작업'], usage: ['OFFICE INTELLIGENCE', '오피스 대시보드'], settings: ['LOCAL CONFIG', '설정'],
  capabilities: ['CLI TOOLING', 'Code Agents'],
};
let state = { agents: [], cards: [], schedules: [], missions: [], settings: {}, presets: {roles:[],workflows:[],tasks:[]}, repository: {valid:false}, capabilities: {clients:[]}, github: null };
let page = 'workspace';
let workspaceTab = 'overview';
let selectedCapability = '';

function toast(message) {
  const el = $('#toast'); el.textContent = message; el.classList.add('show');
  clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 2600);
}
const agentOf = (id) => state.agents.find((a) => a.id === id);
const presetOf = (id) => state.presets.roles.find((preset) => preset.id === id);
const workflowOf = (id) => (state.presets.workflows||[]).find((workflow) => workflow.id === id);
const routingLabel = (project) => project?.routingMode==='manual'?'마스터 직접 처리':project?.routingMode==='sequential'?'지정 순서 실행':workflowOf(project?.workflowId)?.name||'작업 맞춤 자동 라우팅';
const projectOf = (id) => { const project=(state.settings.projects || []).find((item) => item.id === id); return project ? { routingMode:'adaptive', workflowId:'auto', ...project, agentIds: project.agentIds || [], pipeline: project.pipeline || [], teams:(project.teams||[]).map(team=>({...team,agentIds:team.agentIds||[],pipeline:team.pipeline||[]})) } : null; };
const activeProject = () => projectOf(state.settings.activeProjectId) || projectOf((state.settings.projects || [])[0]?.id) || null;
const projectAgents = (project = activeProject()) => project ? (project.agentIds || []).map(agentOf).filter(Boolean) : [];
const visibleCards = () => activeProject() ? state.cards.filter((card) => card.projectId === activeProject().id || (!card.projectId && card.workdir === activeProject().path)) : [];
const cardsOf = (id) => state.cards.filter((c) => c.agentId === id);
const liveCard = (id) => cardsOf(id).find((c) => c.status === 'running') || cardsOf(id).find((c) => c.status === 'review');
const shortTime = (iso) => iso ? new Date(iso).toLocaleString('ko-KR', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
function mergeCard(card){
  const index=state.cards.findIndex(item=>item.id===card.id),current=state.cards[index];
  if(current&&new Date(current.updatedAt||0)>new Date(card.updatedAt||0))return current;
  if(index>=0)state.cards[index]=card;else state.cards.unshift(card);
  return card;
}

async function load() {
  const [next,presets] = await Promise.all([api('/api/state'),api('/api/presets')]);
  const projectId=next.settings.activeProjectId||next.settings.projects?.[0]?.id||'';
  const repository=await api('/api/repository?projectId='+encodeURIComponent(projectId)).catch(error=>({valid:false,git:false,error:error.message}));
  const capabilities=repository.valid?await api('/api/capabilities?projectId='+encodeURIComponent(projectId)).catch(()=>({clients:[]})):{clients:[]};
  const github=page==='workspace'&&projectId&&repository.git?await api('/api/github?projectId='+encodeURIComponent(projectId)).catch(error=>({error:error.message,issues:[],projects:[],pullRequests:[]})):{issues:[],projects:[],pullRequests:[]};
  state = { ...next, presets, repository, capabilities, github };
  if(!repository.valid&&!['workspace','settings'].includes(page))page='workspace';
  render();
}

async function navigate(next) {
  if($('.nav[data-page="'+next+'"]')?.classList.contains('requires-office')&&!state.repository.valid){toast('먼저 작업할 로컬 폴더로 Office를 설정하세요.');next='workspace';}
  page = next; $$('.nav').forEach((b) => b.classList.toggle('active', b.dataset.page === page));
  [$('#eyebrow').textContent, $('#page-title').textContent] = viewInfo[page];
  $('#new-task').hidden = page === 'settings'||page==='workspace'||!state.repository.valid;
  if(page==='workspace'&&activeProject()){
    $('#page').innerHTML='<section class="panel"><div class="empty">Office와 Git 상태를 동기화하는 중…</div></section>';
    const projectId=activeProject()?.id||'';
    state.repository=await api('/api/repository?projectId='+encodeURIComponent(projectId)).catch(error=>({valid:false,error:error.message}));
    state.github=state.repository.git?await api('/api/github?projectId='+encodeURIComponent(projectId)).catch(error=>({error:error.message,issues:[],projects:[]})):{issues:[],projects:[],pullRequests:[]};
  }
  render();
}

function stats() {
  return `<div class="stats"><div class="stat"><span>에이전트</span><b>${state.agents.length}</b></div><div class="stat"><span>실행/대기</span><b>${state.cards.filter(c=>c.status==='running'||c.status==='queued').length}</b></div><div class="stat"><span>검토 대기</span><b>${state.cards.filter(c=>c.status==='review').length}</b></div><div class="stat"><span>완료</span><b>${state.cards.filter(c=>c.status==='done').length}</b></div></div>`;
}

function render() {
  officeStage.unmount();
  renderSidebarRepo();
  renderNavigationState();
  const root = $('#page');
  if (page === 'workspace') root.innerHTML = workspaceView();
  if (page === 'office') root.innerHTML = officeView();
  if (page === 'board') root.innerHTML = boardView();
  if (page === 'history') root.innerHTML = historyView();
  if (page === 'agents') root.innerHTML = agentsView();
  if (page === 'schedules') root.innerHTML = officeSchedulesView();
  if (page === 'usage') root.innerHTML = usageView();
  if (page === 'capabilities') root.innerHTML = capabilitiesView();
  if (page === 'settings') root.innerHTML = settingsView();
  bindPage();
}

function renderNavigationState(){const ready=Boolean(state.repository?.valid);$$('.requires-office').forEach(button=>{button.disabled=!ready;button.title=ready?'':'먼저 Office 작업 폴더를 설정하세요.';});$('#new-task').hidden=page==='settings'||page==='workspace'||!ready;$$('.nav').forEach(button=>button.classList.toggle('active',button.dataset.page===page));const info=viewInfo[page]||viewInfo.workspace;[$('#eyebrow').textContent,$('#page-title').textContent]=info;}

function renderSidebarRepo(){const box=$('#sidebar-repo'),project=activeProject(),valid=state.repository?.valid,git=state.repository?.git;if(!box)return;box.innerHTML=`<label>ACTIVE OFFICE</label><select aria-label="활성 Office">${(state.settings.projects||[]).map(p=>`<option value="${p.id}" ${p.id===project?.id?'selected':''}>${esc(p.name)}</option>`).join('')||'<option value="">Office 설정 필요</option>'}</select><button type="button" title="Office 설정">${project?'⚙':'＋'}</button><small class="${valid?'ready':'invalid'}">${valid?(git?'● 폴더 + Git':'● 로컬 폴더'):'○ 설정 필요'} · ${esc(project?.path||'작업할 로컬 폴더를 연결하세요')}</small>`;const select=$('select',box);select?.addEventListener('change',async()=>{await api('/api/settings',{method:'PUT',body:{activeProjectId:select.value}});page='workspace';await load();});$('button',box)?.addEventListener('click',()=>openProject(project?.id));}

function officeView() {
  const project=activeProject(), agents=projectAgents(project), cards=visibleCards(), teams=project?.teams||[];
  const active=cards.filter(c=>c.status==='running'||c.status==='queued').length,review=cards.filter(c=>c.status==='review').length;
  const readiness=[
    {ok:Boolean(state.settings.defaultWorkdir||(state.settings.projects||[]).length),label:'작업 폴더'},
    {ok:Boolean(agents.length),label:'에이전트'},
    {ok:Boolean(agents.length&&agents.every(a=>a.presetId||a.systemPrompt)),label:'역할 지시'},
    {ok:Boolean(teams.length),label:'팀 구성'},
    {ok:Boolean(agents.length&&agents.every(agent=>state.settings.adapters?.[agent.adapter]?.executable)),label:'실행 어댑터'},
  ];
  const readyCount=readiness.filter(item=>item.ok).length;
  const shelf=(status,label)=>{const rows=cards.filter(c=>c.status===status).slice(0,6);return `<section class="office-shelf"><h3><span>${label}</span><b>${cards.filter(c=>c.status===status).length}</b></h3><div class="office-shelf-list">${rows.map(c=>`<button class="office-mini-card" data-card="${c.id}">${esc(c.title)}</button>`).join('')||'<div class="office-shelf-empty">비어 있음</div>'}</div></section>`;};
  const selector='';
  const missionRows=(state.missions||[]).filter(m=>!project||m.projectId===project.id).slice(0,5);
  const teamOptions=teams.map(team=>`<option value="__team__:${team.id}">★ ${esc(team.name)} · 리드 ${esc(agentOf(team.leadAgentId)?.name||'미지정')} · ${esc(routingLabel(team))}</option>`).join('');
  return `<div class="office-dashboard">${selector}<section class="office-readiness"><div><b>시작 준비 ${readyCount}/${readiness.length}</b><span>${readyCount===readiness.length?'바로 작업을 맡길 수 있습니다.':'빠진 항목을 누르면 해당 설정으로 이동합니다.'}</span></div><div class="readiness-items">${readiness.map((item,i)=>`<button data-ready="${i}" class="${item.ok?'ok':''}">${item.ok?'✓':'○'} ${item.label}</button>`).join('')}</div></section><div class="office-statusbar"><div><h3>${esc(project?.name||'Local Agent Office')}</h3><p>${project?'repo 전담 멀티 에이전트 오피스':'repo를 고르면 전담 팀이 표시됩니다.'}</p></div><div class="office-live-summary"><span>팀 <b>${teams.length}</b></span><span>직원 <b>${agents.length}</b></span><span>작업/검토 <b>${active+review}</b></span></div></div><div class="office-canvas-frame"><button class="office-add-agent" id="office-add-agent">＋ 에이전트 생성</button><canvas id="office-stage" aria-label="에이전트 가상 오피스"></canvas></div><div class="office-roster">${agents.map(a=>{const preset=presetOf(a.presetId);return `<button class="office-agent-chip" data-agent="${a.id}"><i style="background:${a.color}"></i><span><b>${esc(a.name)}</b><small>${esc(preset?.name||a.role||'역할 미지정')} · ${esc(a.modeId||preset?.modeId||'custom')}</small></span></button>`;}).join('')}</div><section class="office-launcher"><div class="launcher-main"><select id="office-agent">${teamOptions}${!teams.length&&project?.agentIds?.length?`<option value="__master__">★ Office 기본 관리자 · ${esc(routingLabel(project))}</option>`:''}${agents.map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(presetOf(a.presetId)?.name||a.role||a.adapter)}</option>`).join('')||'<option value="">배치된 에이전트가 필요합니다</option>'}</select><textarea id="office-prompt" placeholder="팀 또는 직원을 선택하고 할 일을 적으세요 · Enter 실행"></textarea><button class="launcher-settings" id="office-task-options" title="상세 작업 만들기">⚙</button><button class="primary" id="office-send" ${agents.length?'':'disabled'}>보내기</button></div><div class="launcher-hints"><span>${project?.executionMode==='isolated-worktrees'?'Worktree 격리 모드':'동일 repo 쓰기 직렬 보호'}</span><span>${esc(project?.path||state.settings.defaultWorkdir||'기본 작업 폴더')}</span><span>${teams.length?`${teams.length}개 팀별 리드·규칙·워크플로 적용`:`${esc(routingLabel(project))} · 팀 구성을 권장합니다`}</span></div></section>${missionRows.length?`<section class="panel mission-strip"><h3>멀티 에이전트 미션</h3>${missionRows.map(m=>`<div><span class="status-pill ${m.status}">${esc(m.status)}</span><b>${esc(m.title)}</b><small>${m.teamName?`${esc(m.teamName)} · `:''}${esc(workflowOf(m.workflowId)?.name||m.workflowId||'직접')} · ${Math.min(m.stepIndex+1,m.pipeline.length)}/${m.pipeline.length} 단계</small></div>`).join('')}</section>`:''}<div class="office-shelves">${shelf('todo','TO-DO 선반')}${shelf('review','REVIEW 선반')}${shelf('done','DONE 선반')}</div></div>`;
}

const columns = [['todo','할 일'],['queued','대기열'],['running','작업 중'],['review','검토'],['done','완료']];
function boardView() {
  const cards=visibleCards(); return `<div class="board">${columns.map(([key,label]) => { const list=cards.filter(c=>c.status===key); return `<section class="column"><div class="column-head"><span>${label}</span><span class="count">${list.length}</span></div>${list.map(cardHtml).join('') || '<div class="empty" style="padding:35px 4px;font-size:11px">비어 있음</div>'}</section>`; }).join('')}</div>`;
}
function cardHtml(c) { const a=agentOf(c.agentId)||{name:'삭제된 에이전트',color:'#999'}; return `<article class="card" data-card="${c.id}"><h3>${esc(c.title)}</h3><div class="card-meta"><span class="mini-agent"><i style="background:${a.color}"></i>${esc(a.name)}</span><span>${shortTime(c.updatedAt)}</span></div></article>`; }

function eventResultText(event){const data=event?.data||event||{},item=data.item||{};if(data.type==='item.completed'&&item.type==='agent_message')return String(item.text||'').trim();const content=Array.isArray(data.message?.content)?data.message.content:Array.isArray(data.content)?data.content:[];const text=content.filter(part=>part?.type==='text'&&part.text).map(part=>part.text).join('\n').trim();if(text)return text;if(data.type==='text'&&data.part?.text)return String(data.part.text).trim();return '';}
function cardFinalResult(card){for(const event of [...(card?.events||[])].reverse()){const text=eventResultText(event);if(text)return text;}return '';}
function historyView(){return `<section class="panel history-filter"><div><h3>실행 기록</h3><p>작업별 지시, 최종 결과, 원본 로그, 재실행 이력을 확인할 수 있습니다.</p></div><div class="row"><div class="field"><label>제목·지시·결과·로그 검색</label><input id="history-query" placeholder="검색어를 입력하세요"></div><div class="field"><label>상태</label><select id="history-status"><option value="">전체</option>${columns.map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></div></div></section><div id="history-results" class="history-list">${historyResults('', '')}</div>`;}
function historyResults(query,status){const q=query.trim().toLowerCase();const rows=state.cards.filter(c=>(!status||c.status===status)&&(!q||`${c.title}\n${c.prompt}\n${c.output}\n${cardFinalResult(c)}\n${(c.followups||[]).map(f=>f.text).join('\n')}`.toLowerCase().includes(q)));return rows.map(c=>{const a=agentOf(c.agentId)||{},project=projectOf(c.projectId),team=project?.teams?.find(t=>t.id===c.teamId),result=cardFinalResult(c),snippet=(result||c.output||c.prompt||'').replace(/\s+/g,' ').slice(0,180),duration=c.durationMs!=null?`${(c.durationMs/1000).toFixed(1)}초`:'실행 시간 없음';return `<article class="panel history-item" data-card="${c.id}" tabindex="0" role="button" aria-label="${esc(c.title)} 상세 기록 보기"><div><div class="history-title-line"><span class="status-pill ${c.status}">${esc(c.status)}</span><h3>${esc(c.title)}</h3></div><p>${esc(snippet||'아직 기록된 결과가 없습니다.')}</p><div class="history-context"><span>${esc(project?.name||'Office 미지정')}</span>${team?`<span>${esc(team.name)}</span>`:''}<span>${duration}</span><span>실행 ${(c.runs||[]).length+Number(Boolean(c.startedAt))}회</span></div></div><div class="history-meta"><b>${esc(a.name||'알 수 없음')}</b><span>${shortTime(c.updatedAt)}</span><em>상세 기록 보기 →</em></div></article>`;}).join('')||'<div class="empty">일치하는 작업 기록이 없습니다.</div>';}

function projectsView(){const rows=state.settings.projects||[];return `<div class="settings"><section class="panel"><div style="display:flex;justify-content:space-between;align-items:center"><div><h3>Repo 오피스 관리</h3><p style="margin:0;color:var(--muted);font-size:11px">Office는 Git repo와 직원 풀을 관리하고, 리드·라우팅·워크플로는 팀마다 독립적으로 설정합니다.</p></div><button class="primary" id="add-project">＋ Repo</button></div></section>${rows.map(raw=>{const p=projectOf(raw.id),teams=p.teams||[],leads=teams.map(team=>agentOf(team.leadAgentId)?.name).filter(Boolean);return `<section class="panel project-card"><div><h3>${esc(p.name)} ${p.id===activeProject()?.id?'<span class="role-badge assigned">현재 오피스</span>':''}</h3><p>${esc(p.description||'설명 없음')}</p><code>${esc(p.path)}</code><div class="repo-team">직원 <b>${p.agentIds.length}명</b> · 팀 <b>${teams.length}개</b>${leads.length?` · 리드 ${esc(leads.join(', '))}`:''} · ${p.executionMode==='isolated-worktrees'?'worktree 격리':'동일 경로 직렬 보호'}</div></div><div class="actions"><button class="primary select-project" data-id="${p.id}">오피스 열기</button><button class="secondary edit-project" data-id="${p.id}">설정</button><button class="secondary task-project" data-path="${esc(p.path)}">단일 작업</button><button class="danger delete-project" data-id="${p.id}">삭제</button></div></section>`;}).join('')||'<div class="empty"><div class="big">▰</div><b>등록된 repo가 없습니다</b><p>Git 저장소를 등록하고 전담 팀을 배치하세요.</p></div>'}</div>`;}

const workspaceTabs=[['overview','개요',false],['issues','Issues',true],['kanban','GitHub Projects',true],['pulls','Pull Requests',true],['branches','Branches',true],['history','History',true],['worktrees','Worktrees',true]];
function workspaceView(){
  const project=activeProject(),repo=state.repository||{},git=state.github||{issues:[],projects:[],pullRequests:[]},offices=state.settings.projects||[];
  if(!repo.git&&workspaceTab!=='overview')workspaceTab='overview';
  if(!project)return `<div class="office-onboarding"><section class="panel onboarding-hero"><span>01</span><div><p class="eyebrow">START HERE</p><h2>로컬 폴더로 첫 Office를 만드세요</h2><p>Git이 아직 없어도 폴더만 지정하면 에이전트, 팀, 작업과 자동화를 바로 사용할 수 있습니다. 나중에 Git을 초기화하고 새로고침하면 Git 기능이 자동으로 열립니다.</p><button class="primary" id="add-project">＋ 작업 폴더 연결</button></div></section><div class="setup-flow"><article class="active"><b>1</b><span>Office</span><small>로컬 폴더 연결</small></article><article><b>2</b><span>Code Agents</span><small>CLI와 도구 확인</small></article><article><b>3</b><span>Team</span><small>에이전트 배치</small></article><article><b>4</b><span>Work</span><small>작업 실행</small></article></div></div>`;
  const summary=`<section class="panel repo-command"><div><span class="repo-state ${repo.valid?'ready':'invalid'}">${repo.valid?(repo.git?'● FOLDER + GIT':'● LOCAL FOLDER'):'○ INVALID'}</span><h2>${esc(project.name)}</h2><code>${esc(project.path)}</code><p>${esc(project.description||'로컬 폴더 전담 멀티 에이전트 Office')}</p></div><div class="repo-facts"><span><small>BRANCH</small><b>${esc(repo.git?(repo.branch||'-'):'Git 미연결')}</b></span><span><small>CHANGES</small><b>${repo.git?(repo.changes?.length||0):'-'}</b></span><span><small>AGENTS</small><b>${projectAgents(project).length}</b></span><span><small>MODE</small><b>${repo.git?(git.slug?'GitHub':'Local Git'):'Folder'}</b></span></div><div class="actions"><button class="secondary" id="refresh-workspace">새로고침</button><button class="secondary" id="edit-office">Office 설정</button><button class="primary" id="add-project">＋ Office</button></div></section>`;
  const tabs=`<div class="workspace-tabs">${workspaceTabs.map(([id,label,gitOnly])=>`<button class="${workspaceTab===id?'active':''}" data-workspace-tab="${id}" ${gitOnly&&!repo.git?'disabled title="Git 연결 후 사용할 수 있습니다"':''}>${label}</button>`).join('')}</div>`;
  return `<div class="workspace-page">${summary}${repo.valid?'':`<div class="error-box"><b>이 Office는 활성화할 수 없습니다.</b><span>${esc(repo.error||'유효한 Git 저장소가 아닙니다.')}</span></div>`}${tabs}${workspaceTabView(project,repo,git,offices)}</div>`;
}

function workspaceTabView(project,repo,git,offices){
  if(workspaceTab==='overview')return `<div class="workspace-overview"><section class="panel hierarchy-panel"><div class="inventory-head"><div><h3>Office hierarchy</h3><p>지정한 로컬 폴더가 모든 팀과 작업의 경계입니다.</p></div><span>${repo.git?'Git 연결':'폴더 모드'}</span></div>${!repo.git?'<div class="success-box"><b>Git 없이 작업 중</b><span>이 폴더에서 Git을 초기화한 뒤 새로고침하면 branch·history·GitHub 기능이 자동 활성화됩니다.</span></div>':''}<div class="hierarchy-tree"><div class="root"><b>▰ ${esc(project.name)}</b><small>${esc(repo.root||project.path)}</small></div><div><article><b>⌘ Code Agents</b><small>${state.capabilities?.clients?.length||0}개 CLI 프로필</small></article><article><b>◆ Teams</b><small>${project.teams?.length||0}개 팀 · ${projectAgents(project).length}명</small></article><article><b>▦ Work</b><small>${visibleCards().length}개 작업</small></article><article><b>◈ Git</b><small>${repo.git?(git.slug||'로컬 Git'):'나중에 연결 가능'}</small></article></div></div></section><section class="panel office-list"><div class="inventory-head"><h3>등록된 Office</h3><span>${offices.length}개</span></div>${offices.map(item=>`<article class="${item.id===project.id?'active':''}"><div><b>${esc(item.name)}</b><small>${esc(item.path)}</small></div><button class="secondary select-project" data-id="${item.id}">${item.id===project.id?'열림':'열기'}</button></article>`).join('')}</section></div>`;
  if(workspaceTab==='issues')return `<section class="panel"><div class="inventory-head"><div><h3>GitHub Issues</h3><p>${git.authenticated?'요청을 Office 작업으로 가져올 수 있습니다.':'GitHub origin과 gh 인증이 필요합니다.'}</p></div><button class="primary" id="create-github-issue" ${git.authenticated?'':'disabled'}>＋ Issue</button></div>${git.error?`<div class="error-box">${esc(git.error)}</div>`:''}<div class="issue-list">${(git.issues||[]).map(issue=>`<article><span class="status-pill ${issue.state==='OPEN'?'running':'done'}">${esc(issue.state)}</span><div><b>#${issue.number} ${esc(issue.title)}</b><small>${shortTime(issue.updatedAt)} · ${(issue.labels||[]).map(label=>esc(label.name)).join(', ')||'label 없음'}</small></div><button class="secondary import-issue" data-number="${issue.number}">작업으로 가져오기</button></article>`).join('')||'<div class="empty">표시할 Issue가 없습니다.</div>'}</div></section>`;
  if(workspaceTab==='kanban')return `<section class="panel"><div class="inventory-head"><div><h3>GitHub Projects v2</h3><p>로컬 작업 보드와 별개인 GitHub Project를 읽기 전용으로 표시합니다.</p></div><div class="actions"><button class="secondary" id="open-local-board">로컬 작업 보드</button><span>${git.projects?.length||0}개</span></div></div>${git.projectError?`<div class="permission-box"><b>${git.projectPermissionMissing?'GitHub Projects 읽기 권한이 아직 없습니다':'Projects를 불러오지 못했습니다'}</b><span>${git.projectPermissionMissing?'현재 gh 로그인은 유효하지만 Projects v2만 읽을 수 없습니다. Issues·PR·로컬 작업은 계속 사용할 수 있습니다.':esc(git.projectError)}</span>${git.projectPermissionMissing?'<code>gh auth refresh -s read:project</code><small>터미널에서 한 번 실행하고 GitHub 승인 후 새로고침하세요.</small>':''}</div>`:''}<div class="kanban-projects">${(git.projects||[]).map(board=>`<article><header><b>▦ ${esc(board.title||`Project ${board.number}`)}</b><small>#${board.number} · ${(board.items||[]).length} items</small></header><div>${(board.items||[]).slice(0,30).map(item=>`<span><em>${esc(item.status||item.type||'No status')}</em><b>${esc(item.title||item.content?.title||'Untitled')}</b></span>`).join('')||'<small>표시할 항목이 없습니다.</small>'}</div></article>`).join('')||'<div class="empty">연결된 GitHub Project가 없습니다.</div>'}</div></section>`;
  if(workspaceTab==='pulls')return `<section class="panel"><div class="inventory-head"><h3>Pull Requests</h3><span>${git.pullRequests?.length||0}건</span></div><div class="git-rows">${(git.pullRequests||[]).map(pr=>`<a href="${esc(pr.url)}" target="_blank" rel="noreferrer"><span class="status-pill ${pr.state==='OPEN'?'running':'done'}">${pr.isDraft?'DRAFT':esc(pr.state)}</span><div><b>#${pr.number} ${esc(pr.title)}</b><small>${esc(pr.headRefName)} → ${esc(pr.baseRefName)} · ${shortTime(pr.updatedAt)}</small></div></a>`).join('')||'<div class="empty">Pull Request가 없습니다.</div>'}</div></section>`;
  if(workspaceTab==='branches')return `<section class="panel"><div class="inventory-head"><div><h3>Branches</h3><p>로컬과 remote branch를 최근 변경 순으로 표시합니다.</p></div><span>${repo.branches?.length||0}개</span></div><div class="git-rows">${(repo.branches||[]).map(branch=>`<article><span class="branch-icon">⑂</span><div><b>${esc(branch.name)} ${branch.current?'<em>current</em>':''}</b><small>${esc(branch.upstream||'upstream 없음')} · ${shortTime(branch.updatedAt)}</small></div></article>`).join('')}</div></section>`;
  if(workspaceTab==='history')return `<section class="panel"><div class="inventory-head"><div><h3>Commit History</h3><p>${esc(repo.branch||'현재 branch')} 최근 커밋</p></div><span>${repo.commits?.length||0}개</span></div><div class="commit-list">${(repo.commits||[]).map(commit=>`<article><code>${esc(commit.shortHash)}</code><div><b>${esc(commit.subject)}</b><small>${esc(commit.author)} · ${shortTime(commit.authoredAt)}</small></div></article>`).join('')}</div></section>`;
  return `<div class="worktree-layout"><section class="panel"><div class="inventory-head"><div><h3>Agent Worktrees</h3><p>격리 모드에서는 에이전트마다 전용 branch와 작업 폴더를 자동 준비합니다.</p></div><span>${repo.worktrees?.length||0}개</span></div><div class="git-rows">${(repo.worktrees||[]).map(tree=>`<article><span class="branch-icon">⌘</span><div><b>${esc(tree.branch||'detached')}</b><small>${esc(tree.path)}</small></div></article>`).join('')}</div></section><section class="panel"><h3>충돌 방지 상태</h3><p>${project.executionMode==='isolated-worktrees'?'에이전트별 worktree 격리가 활성화되어 있습니다.':'같은 repo 경로의 쓰기 작업을 직렬화합니다.'}</p>${repo.dirty?`<div class="warning-box"><b>기준 repo에 미커밋 변경 ${repo.changes.length}건</b><span>새 worktree에는 이 변경이 포함되지 않습니다.</span></div>`:'<div class="success-box">기준 repo가 깨끗합니다.</div>'}<div class="worktree-actions">${projectAgents(project).map(agent=>`<button class="secondary prepare-worktree" data-agent="${agent.id}" ${project.executionMode==='isolated-worktrees'?'':'disabled'}>${esc(agent.name)} 전용 worktree 준비</button>`).join('')||'<small>먼저 에이전트를 배치하세요.</small>'}</div></section></div>`;
}

function agentsView() {
  const project=activeProject(),agents=projectAgents(project),teams=project?.teams||[];
  const org=teams.map(team=>`<article class="team-unit"><header><span>TEAM</span><b>${esc(team.name)}</b><small>${esc(routingLabel(team))}</small></header><div class="team-lead">★ ${esc(agentOf(team.leadAgentId)?.name||'리드 미지정')}</div><div class="team-members">${team.agentIds.map(id=>agentOf(id)).filter(Boolean).map(agent=>`<span><i style="background:${agent.color}"></i>${esc(agent.name)}</span>`).join('')}</div><footer>${esc(workflowOf(team.workflowId)?.name||'작업 맞춤 자동 라우팅')}</footer></article>`).join('');
  return `<section class="panel team-context"><div><span class="role-badge assigned">${esc(project?.name)}</span><h3>Office 조직과 사용자 에이전트</h3><p>역할 프리셋은 전문성 템플릿이고, 실제 직원은 별도의 CLI 어댑터·모델·사용자 지시를 가집니다.</p></div><button class="primary" id="edit-office-team">팀·리드·워크플로 관리</button></section><section class="panel org-section"><div class="inventory-head"><div><h3>팀 조직도</h3><p>한 Office에 여러 리드와 파트별 직원을 구성할 수 있습니다.</p></div><span>${teams.length}개 팀</span></div><div class="team-units">${org||'<button class="empty add-first-team" type="button">아직 팀이 없습니다. 첫 팀과 마스터를 구성하세요.</button>'}</div></section><section class="panel"><h3>개발 오피스 역할 프리셋</h3><p>프리셋에는 어댑터나 모델이 포함되지 않습니다. 역할 지식·모드·전문 태그만 제공하고, 직원을 만들 때 실행 환경과 개인 지시를 선택합니다.</p><div class="preset-row">${state.presets.roles.map(r=>`<button class="preset-agent" data-preset="${r.id}"><i style="background:${r.color}"></i><b>${esc(r.name)}</b><span>${esc(r.role)}</span><em>${esc(r.modeId)} · ${(r.tags||[]).map(esc).join(' · ')}</em></button>`).join('')}</div></section><div class="agent-grid" style="margin-top:14px">${agents.map(a=>{const preset=presetOf(a.presetId),adapter=state.settings.adapters?.[a.adapter],mode=a.modeId||preset?.modeId||'custom',memberships=teams.filter(team=>team.agentIds.includes(a.id)).map(team=>`${team.leadAgentId===a.id?'★ ':''}${team.name}`);return `<article class="panel agent-card"><div class="agent-line"><div class="avatar" style="background:${a.color};color:${a.color}"><span style="color:#fff">${esc(a.name.slice(0,2).toUpperCase())}</span></div><div><b>${esc(a.name)}</b><small>${esc(adapter?.label||a.adapter)}${a.model?' · '+esc(a.model):''}</small></div></div><span class="role-badge ${preset?'assigned':'custom'}">${esc(mode)} · ${preset?esc(preset.name):'사용자 설정'}</span><p>${esc(a.role||'직함과 작업 모드를 지정하세요.')}</p><small>${esc((a.specialties||preset?.tags||[]).join(' · '))}</small><div class="agent-team-tags">${memberships.map(name=>`<span>${esc(name)}</span>`).join('')||'<em>팀 미배치</em>'}</div><div class="actions"><button class="primary role-agent" data-id="${a.id}">${preset?'프리셋 변경':'프리셋 지정'}</button><button class="secondary edit-agent" data-id="${a.id}">직원 설정</button><button class="secondary task-agent" data-id="${a.id}">작업 맡기기</button><button class="danger delete-agent" data-id="${a.id}">삭제</button></div></article>`;}).join('')}<button class="panel agent-card" id="add-agent" style="border-style:dashed;cursor:pointer;min-height:180px;color:var(--muted);font-weight:800">＋ 사용자 에이전트 생성</button></div>`;
}

function schedulesView(){const rows=state.schedules||[],days=['일','월','화','수','목','금','토'];const label=s=>s.type==='interval'?`${s.intervalMinutes}분 간격`:s.type==='daily'?`매일 ${s.time}`:s.type==='weekly'?`매주 ${days[s.weekday]}요일 ${s.time}`:`1회 · ${shortTime(s.runAt)}`;return `<div class="settings"><section class="panel"><div style="display:flex;justify-content:space-between;align-items:center"><div><h3>자동 실행</h3><p style="margin:0;color:var(--muted);font-size:11px">한 번, 간격, 매일, 매주 규칙으로 작업 카드를 만듭니다.</p></div><button class="primary" id="add-schedule">＋ 예약</button></div></section>${rows.map(s=>`<section class="panel"><div style="display:flex;justify-content:space-between;gap:16px"><div><h3>${esc(s.name)}</h3><p>${label(s)} · 다음 ${s.nextRunAt?shortTime(s.nextRunAt):'없음'}${s.error?` · 오류: ${esc(s.error)}`:''}</p></div><div class="actions"><button class="secondary run-schedule" data-id="${s.id}">지금 실행</button><button class="danger delete-schedule" data-id="${s.id}">삭제</button></div></div></section>`).join('')||'<div class="empty"><div class="big">◷</div><b>예약 작업이 없습니다</b><p>반복 리포트나 정기 점검을 자동화할 수 있습니다.</p></div>'}</div>`;}

function usageView(){
  const project=activeProject(),cards=visibleCards(),staff=projectAgents(project),rows={},models={},daily={};
  let input=0,output=0,cached=0,duration=0,runs=0;const details=[];
  for(const c of cards){const agent=agentOf(c.agentId)||{},name=agent.name||'알 수 없음',model=agent.model||state.settings.adapters?.[agent.adapter]?.label||agent.adapter||'unknown';rows[name]||={input:0,output:0,duration:0,runs:0,model};models[model]||={input:0,output:0,runs:0};for(const run of [...(c.runs||[]),c]){if(!run.startedAt)continue;if(run.finishedAt){runs++;rows[name].runs++;models[model].runs++;}const d=Number(run.durationMs||0);duration+=d;rows[name].duration+=d;let ri=0,ro=0,rc=0;for(const e of run.events||[]){const u=e.data?.usage;if(u){ri+=Number(u.input_tokens||0);ro+=Number(u.output_tokens||0);rc+=Number(u.cached_input_tokens||0);}}const at=run.finishedAt||run.startedAt,date=String(at).slice(0,10);input+=ri;output+=ro;cached+=rc;rows[name].input+=ri;rows[name].output+=ro;models[model].input+=ri;models[model].output+=ro;daily[date]=(daily[date]||0)+ri+ro;details.push({title:c.title,agent:name,model,status:c.status,input:ri,output:ro,duration:d,at});}}
  const total=input+output,maxAgent=Math.max(1,...Object.values(rows).map(r=>r.input+r.output)),maxModel=Math.max(1,...Object.values(models).map(r=>r.input+r.output));
  const leader=Object.entries(rows).sort((a,b)=>(b[1].input+b[1].output)-(a[1].input+a[1].output))[0];
  const dates=[];for(let offset=83;offset>=0;offset--){const day=new Date();day.setHours(12,0,0,0);day.setDate(day.getDate()-offset);dates.push(day.toISOString().slice(0,10));}
  const heatMax=Math.max(1,...dates.map(date=>daily[date]||0));
  const recent=dates.slice(-14),recentMax=Math.max(1,...recent.map(date=>daily[date]||0));
  const heat=dates.map(date=>{const value=daily[date]||0,level=value?Math.max(1,Math.ceil(value/heatMax*4)):0;return `<i class="l${level}" title="${date} · ${value.toLocaleString()} tokens"></i>`;}).join('');
  return `<div class="office-dashboard-page"><section class="panel usage-filter"><div><span class="dashboard-kicker">LOCAL · PRIVATE</span><h3>${esc(project?.name||'전체')} 오피스 인텔리전스</h3><p>직원·세션·토큰 지출을 로컬 기록에서만 집계합니다. 통화 비용은 모델별 단가 설정 전까지 추정하지 않습니다.</p></div><select id="usage-repo"><option value="">전체 repo</option>${(state.settings.projects||[]).map(p=>`<option value="${p.id}" ${p.id===project?.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></section><div class="dashboard-stats"><article><span>오피스 직원</span><b>${staff.length}<small>명</small></b><em>${staff.filter(a=>cards.some(c=>c.agentId===a.id&&['running','queued'].includes(c.status))).length}명 근무 중</em></article><article><span>토큰 급여 · 지출량</span><b>${total.toLocaleString()}<small>tok</small></b><em>입력 ${input.toLocaleString()} · 출력 ${output.toLocaleString()}</em></article><article><span>완료 세션</span><b>${runs}<small>회</small></b><em>총 ${Math.round(duration/60000)}분 실행</em></article><article><span>이번 기간 MVP</span><b>${esc(leader?.[0]||'-')}</b><em>${leader?`${(leader[1].input+leader[1].output).toLocaleString()} tokens`:'실행 기록 없음'}</em></article></div><div class="dashboard-grid"><section class="panel activity-panel"><div class="inventory-head"><div><h3>84일 활동 히트맵</h3><p>GitHub 잔디처럼 실행 토큰이 기록된 날을 표시합니다.</p></div><span>${Object.values(daily).filter(Boolean).length} active days</span></div><div class="token-heatmap">${heat}</div><div class="heat-legend"><span>적음</span><i class="l0"></i><i class="l1"></i><i class="l2"></i><i class="l3"></i><i class="l4"></i><span>많음</span></div></section><section class="panel"><div class="inventory-head"><div><h3>최근 14일 토큰</h3><p>날짜별 입력+출력 합계</p></div><b>${total.toLocaleString()}</b></div><div class="daily-bars">${recent.map(date=>{const value=daily[date]||0;return `<span title="${date} · ${value.toLocaleString()} tokens"><i style="height:${Math.max(value?8:2,value/recentMax*100)}%"></i><small>${date.slice(5).replace('-','/')}</small></span>`;}).join('')}</div></section></div><div class="dashboard-grid"><section class="panel"><h3>직원별 토큰 급여 원장</h3>${Object.entries(rows).sort((a,b)=>(b[1].input+b[1].output)-(a[1].input+a[1].output)).map(([name,r],index)=>`<div class="usage-row ranked"><em>#${index+1}</em><span>${esc(name)}<small>${esc(r.model)} · ${r.runs}회 · ${Math.round(r.duration/60000)}분</small></span><div><i style="width:${Math.max(3,(r.input+r.output)/maxAgent*100)}%"></i></div><b>${(r.input+r.output).toLocaleString()} tok</b></div>`).join('')||'<div class="empty">아직 실행 기록이 없습니다.</div>'}</section><section class="panel"><h3>모델별 소비</h3>${Object.entries(models).sort((a,b)=>(b[1].input+b[1].output)-(a[1].input+a[1].output)).map(([name,r])=>`<div class="model-usage"><span><b>${esc(name)}</b><small>${r.runs} sessions</small></span><div><i style="width:${Math.max(3,(r.input+r.output)/maxModel*100)}%"></i></div><strong>${(r.input+r.output).toLocaleString()}</strong></div>`).join('')||'<div class="empty">모델 사용 기록이 없습니다.</div>'}</section></div><section class="panel"><div class="inventory-head"><div><h3>세션 원장</h3><p>최근 실행 50건</p></div><span>캐시 입력 ${cached.toLocaleString()}</span></div><div class="usage-table"><div class="usage-table-head"><span>작업</span><span>직원 / 모델</span><span>입력</span><span>출력</span><span>시간</span></div>${details.sort((a,b)=>String(b.at).localeCompare(String(a.at))).slice(0,50).map(r=>`<div><span>${esc(r.title)}<small>${shortTime(r.at)}</small></span><span>${esc(r.agent)}<small>${esc(r.model)}</small></span><span>${r.input.toLocaleString()}</span><span>${r.output.toLocaleString()}</span><span>${(r.duration/1000).toFixed(1)}s</span></div>`).join('')||'<div class="empty">상세 실행이 없습니다.</div>'}</div></section></div>`;
}

const capabilityLabels={runtime:'Runtime',mcp:'MCP',skills:'Skills',rules:'Rules / Instructions',plugins:'Plugins',subagents:'Subagents',agents:'Primary agents',commands:'Commands'};
function capabilitiesView(){const clients=state.capabilities?.clients||[];if(!clients.some(client=>client.id===selectedCapability))selectedCapability=clients[0]?.id||'';const selected=clients.find(client=>client.id===selectedCapability);const adapter=state.settings.adapters?.[selectedCapability];return `<div class="tooling-page"><section class="panel tooling-head"><div><h3>${esc(activeProject()?.name||'현재 repo')} Code Agents</h3><p>CLI 프로필을 선택하면 이 Office에 적용된 MCP·Skills·Rules·Plugins·Subagents를 확인할 수 있습니다.</p></div><div class="actions"><span>${shortTime(state.capabilities?.scannedAt)}</span><button class="primary" id="add-adapter">＋ 커스텀 프로필</button></div></section><div class="cli-grid selectable">${clients.map(client=>`<button class="panel cli-card ${client.id===selectedCapability?'selected':''}" data-capability="${esc(client.id)}"><div class="cli-title"><span class="cli-logo ${esc(client.family||client.id)}">${client.family==='opencode'?'OC':client.family==='claude'?'CL':client.family==='codex'?'CX':'LLM'}</span><div><h3>${esc(client.label)}</h3><p>${client.installed?'실행 파일 감지됨':'실행 파일 미감지'}</p></div><span class="status-pill ${client.installed?'done':'review'}">${client.installed?'READY':'SETUP'}</span></div><code>${esc(client.executable||'실행 파일 설정 필요')}</code><div class="cap-counts"><span><b>${client.counts?.mcp||0}</b>MCP</span><span><b>${client.counts?.skills||0}</b>Skills</span><span><b>${client.counts?.subagents||0}</b>Subagents</span></div></button>`).join('')}</div>${selected?`<section class="panel inventory"><div class="inventory-head"><div><h3>${esc(selected.label)} 적용 구성</h3><p>${esc(selected.family)} compatible · 비밀값과 프롬프트 본문은 표시하지 않습니다.</p></div><div class="actions">${adapter&&!adapter.builtIn&&!['codex','claude','opencode','custom'].includes(selected.id)?`<button class="secondary" id="edit-adapter">프로필 편집</button><button class="danger" id="delete-adapter">삭제</button>`:''}<span>global + project + profile</span></div></div>${Object.entries(capabilityLabels).map(([type,label])=>{const rows=(selected.items||[]).filter(item=>item.type===type);return rows.length?`<div class="inventory-group"><h4>${label} <b>${rows.length}</b></h4><div>${rows.map(item=>`<article><span class="scope ${item.scope}">${item.scope}</span><b>${esc(item.name)}</b>${item.mode?`<em>${esc(item.mode)}</em>`:''}${item.model?`<em>${esc(item.model)}</em>`:''}<small title="${esc(item.source)}">${esc(item.detail||item.source)}</small><i class="${item.enabled?'on':'off'}">${item.enabled?'적용':'비활성'}</i></article>`).join('')}</div></div>`:'';}).join('')||'<div class="empty">발견된 구성이 없습니다.</div>'}</section>`:'<div class="empty">CLI 프로필이 없습니다.</div>'}</div>`;}

function itoView(){const clients=state.capabilities?.clients||[],project=activeProject(),owners=projectAgents(project).filter(agent=>['claude','opencode'].includes(agent.adapter));const observed=visibleCards().flatMap(card=>(card.events||[]).filter(event=>event.type==='subagent.started').map(event=>({...event,card})));if(!owners.length&&!observed.length)return '';return `<section class="panel ito-office"><div class="inventory-head"><div><h3>ITO · 서브에이전트 인력풀</h3><p>Claude/OpenCode 담당자가 필요할 때 호출할 수 있는 격리된 전문 인력입니다.</p></div><span>${observed.filter(item=>item.card.status==='running').length}명 투입 중</span></div><div class="ito-grid">${owners.map(owner=>{const pool=clients.find(client=>client.id===owner.adapter)?.items?.filter(item=>item.type==='subagents'&&item.enabled)||[];return `<article class="ito-owner"><div class="agent-line"><i style="background:${owner.color}"></i><span><b>${esc(owner.name)}</b><small>${esc(owner.adapter)} 원청 담당</small></span></div><div class="ito-workers">${pool.slice(0,8).map(worker=>`<span><i>外</i><b>${esc(worker.name)}</b><small>${esc(worker.detail||worker.mode||'전문 subagent')}</small></span>`).join('')||'<em>등록된 서브에이전트 없음</em>'}</div></article>`;}).join('')}</div>${observed.length?`<div class="ito-observed"><b>최근 실제 호출</b>${observed.slice(-8).reverse().map(item=>`<span>${esc(agentOf(item.card.agentId)?.name||'Agent')} → ${esc(item.name)} · ${esc(item.card.title)}</span>`).join('')}</div>`:''}</section>`;}

function githubView(){const git=state.github||{issues:[],projects:[]},project=activeProject();return `<div class="git-page"><section class="panel git-head"><div><h3>${esc(git.slug||project?.name||'GitHub 연결')}</h3><p>${git.authenticated?'origin과 GitHub CLI 인증을 확인했습니다.':'repo의 GitHub origin과 gh 인증이 필요합니다.'}</p></div><div class="actions"><button class="secondary" id="refresh-github">새로고침</button><button class="primary" id="create-github-issue" ${git.authenticated?'':'disabled'}>＋ Issue</button></div></section>${git.error?`<div class="error-box">${esc(git.error)}</div>`:''}<div class="git-layout"><section class="panel"><div class="inventory-head"><h3>Issues</h3><span>${git.issues?.length||0}건</span></div><div class="issue-list">${(git.issues||[]).map(issue=>`<article><span class="status-pill ${issue.state==='OPEN'?'running':'done'}">${esc(issue.state)}</span><div><b>#${issue.number} ${esc(issue.title)}</b><small>${shortTime(issue.updatedAt)} · ${(issue.labels||[]).map(label=>esc(label.name)).join(', ')||'label 없음'}</small></div><button class="secondary import-issue" data-number="${issue.number}">작업으로 가져오기</button></article>`).join('')||'<div class="empty">Issue가 없거나 아직 동기화되지 않았습니다.</div>'}</div></section><section class="panel"><div class="inventory-head"><h3>Projects v2</h3><span>${git.projects?.length||0}개</span></div><div class="project-board-list">${(git.projects||[]).map(board=>`<article><span>▦</span><div><b>${esc(board.title||board.name||`Project ${board.number||''}`)}</b><small>#${board.number||'-'} · ${board.closed?'closed':'active'}</small></div></article>`).join('')||`<div class="empty">${git.projectError?'Projects 권한이 없거나 조회할 수 없습니다.':'연결된 Project가 없습니다.'}</div>`}</div></section></div></div>`;}

function settingsView() {
  const s=state.settings, a=s.adapters||{};
  const detected=s.detected||{};
  return `<div class="settings"><section class="panel"><h3>실행 환경</h3><p>모든 설정은 이 PC에만 저장됩니다. 마지막 자동 감지: ${detected.checkedAt?shortTime(detected.checkedAt):'아직 없음'}</p><div class="row"><div class="field"><label>동시 실행 수</label><input id="set-concurrency" type="number" min="1" max="8" value="${s.concurrency||2}"></div><div class="field"><label>기본 작업 폴더</label><div class="input-action"><input id="set-workdir" value="${esc(s.defaultWorkdir||'')}" placeholder="C:\\workspace"><button type="button" class="secondary" id="pick-default-folder">찾기</button></div></div></div></section><section class="panel"><h3>Windows 데스크톱</h3><p>앱 창을 닫으면 트레이에 유지됩니다.</p><div class="actions"><button class="secondary" id="toggle-autostart" disabled>자동 시작 확인 중…</button></div></section>${['codex','claude','opencode','custom'].map(k=>adapterPanel(k,a[k]||{})).join('')}<button class="primary" id="save-settings">설정 저장</button></div>`;
}
function adapterPanel(key,a){return `<section class="panel"><h3>${esc(a.label||key)} 어댑터</h3><p>명령은 셸을 통하지 않고 직접 실행됩니다.</p><div class="field"><label>실행 파일</label><input id="${key}-exe" value="${esc(a.executable||'')}" placeholder="${key}"></div><div class="field"><label>인자 · 한 줄에 하나</label><textarea id="${key}-args">${esc((a.args||[]).join('\n'))}</textarea><span class="hint">사용 가능: {prompt}, {workdir}, {model}</span></div></section>`;}

function bindPage() {
  if(page==='office'&&$('#office-stage'))officeStage.mount($('#office-stage'),projectAgents(),visibleCards(),id=>openAgent(id));
  if(page==='office'&&!state.repository?.git){const status=$('.office-statusbar p'),hint=$('.launcher-hints span');if(status)status.textContent='로컬 폴더 전담 멀티 에이전트 오피스';if(hint)hint.textContent='동일 폴더 쓰기 직렬 보호';}
  if(page==='office'&&$('.office-shelves'))$('.office-shelves').insertAdjacentHTML('beforebegin',itoView());
  $('#office-repo')?.addEventListener('change',async(e)=>{await api('/api/settings',{method:'PUT',body:{activeProjectId:e.target.value}});await load();});
  $('#edit-active-repo')?.addEventListener('click',()=>openProject(activeProject()?.id));
  $$('.office-agent-chip').forEach(el=>el.onclick=()=>openAgent(el.dataset.agent));
  $$('.readiness-items button').forEach(el=>el.onclick=()=>{const target=Number(el.dataset.ready);if(target===0)navigate('workspace');else if(target===1||target===2)navigate('agents');else if(target===3)openTeamManager();else navigate('capabilities');});
  $$('.desk').forEach(el=>el.onclick=()=>openAgent(el.dataset.agent));
  $$('.office-mini-card').forEach(el=>el.onclick=()=>openCard(el.dataset.card));
  $('#office-add-agent')?.addEventListener('click',()=>openAgent());
  $('#office-task-options')?.addEventListener('click',()=>{const selected=$('#office-agent')?.value||'';if(selected.startsWith('__team__:')){toast('팀 작업은 현재 빠른 발사대에서 목표를 입력하세요.');return;}openTask(selected==='__master__'?'':selected);});
  const quickPrompt=$('#office-prompt');
  const sendQuick=async()=>{const prompt=quickPrompt?.value.trim(),agentId=$('#office-agent')?.value,project=activeProject();if(!prompt||!agentId)return;try{if(agentId==='__master__'||agentId.startsWith('__team__:')){await api('/api/missions',{method:'POST',body:{title:prompt.split(/\r?\n/)[0].slice(0,64),prompt,projectId:project?.id,teamId:agentId.startsWith('__team__:')?agentId.slice(9):''}});}else{const card=await api('/api/cards',{method:'POST',body:{title:prompt.split(/\r?\n/)[0].slice(0,64),prompt,agentId,projectId:project?.id||'',workdir:project?.path||state.settings.defaultWorkdir||''}});await api(`/api/cards/${card.id}/run`,{method:'POST'});}quickPrompt.value='';await load();}catch(e){toast(e.message);}};
  $('#office-send')?.addEventListener('click',sendQuick);
  quickPrompt?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendQuick();}});
  $$('.card').forEach(el=>el.onclick=()=>openCard(el.dataset.card));
  $('#empty-agent')?.addEventListener('click',()=>openAgent()); $('#add-agent')?.addEventListener('click',()=>openAgent());
  $('#edit-office-team')?.addEventListener('click',openTeamManager);
  $('.add-first-team')?.addEventListener('click',()=>openTeamEditor());
  $$('.preset-agent').forEach(el=>el.onclick=()=>openAgent('',el.dataset.preset));
  $$('.edit-agent').forEach(el=>el.onclick=()=>openAgent(el.dataset.id));
  $$('.edit-agent-capabilities').forEach(el=>el.onclick=()=>openAgent(el.dataset.id));
  $$('.role-agent').forEach(el=>el.onclick=()=>openRoleAssign(el.dataset.id));
  $$('.task-agent').forEach(el=>el.onclick=()=>openTask(el.dataset.id));
  $$('.delete-agent').forEach(el=>el.onclick=async()=>{if(confirm('이 에이전트를 삭제할까요?')){await act(()=>api('/api/agents/'+el.dataset.id,{method:'DELETE'}));await load();}});
  const historyQuery=$('#history-query'),historyStatus=$('#history-status');
  const bindHistoryRows=(box=$('#history-results'))=>{if(!box)return;$$('.history-item',box).forEach(el=>{el.onclick=()=>openCard(el.dataset.card);el.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openCard(el.dataset.card);}};});};
  const filterHistory=()=>{const box=$('#history-results');if(!box)return;box.innerHTML=historyResults(historyQuery?.value||'',historyStatus?.value||'');bindHistoryRows(box);};
  bindHistoryRows();
  historyQuery?.addEventListener('input',filterHistory);historyStatus?.addEventListener('change',filterHistory);
  $('#add-project')?.addEventListener('click',()=>openProject());
  $$('.edit-project').forEach(el=>el.onclick=()=>openProject(el.dataset.id));
  $$('.select-project').forEach(el=>el.onclick=async()=>{await api('/api/settings',{method:'PUT',body:{activeProjectId:el.dataset.id}});workspaceTab='overview';page='workspace';await load();});
  $$('.task-project').forEach(el=>el.onclick=()=>openTask('',el.dataset.path));
  $$('.delete-project').forEach(el=>el.onclick=async()=>{if(confirm('이 프로젝트 프리셋을 삭제할까요?')){await act(()=>api('/api/projects/'+el.dataset.id,{method:'DELETE'}));await load();}});
  $('#add-schedule')?.addEventListener('click',()=>openOfficeSchedule());
  $('#add-daily-report')?.addEventListener('click',()=>openOfficeSchedule('daily-report'));
  $$('.open-schedule-card').forEach(el=>el.onclick=()=>openCard(el.dataset.card));
  $$('.run-schedule').forEach(el=>el.onclick=async()=>{await act(()=>api('/api/schedules/'+el.dataset.id+'/run',{method:'POST'}));toast('예약 작업을 실행 대기열에 추가했습니다.');await load();});
  $$('.delete-schedule').forEach(el=>el.onclick=async()=>{if(confirm('이 예약을 삭제할까요?')){await act(()=>api('/api/schedules/'+el.dataset.id,{method:'DELETE'}));await load();}});
  $('#save-settings')?.addEventListener('click',saveSettings);
  $('#refresh-workspace')?.addEventListener('click',()=>navigate('workspace'));
  $('#open-local-board')?.addEventListener('click',()=>navigate('board'));
  $('#edit-office')?.addEventListener('click',()=>openProject(activeProject()?.id));
  $$('[data-workspace-tab]').forEach(el=>el.onclick=()=>{workspaceTab=el.dataset.workspaceTab;render();});
  $$('.prepare-worktree').forEach(el=>el.onclick=async()=>{try{el.disabled=true;el.textContent='준비 중…';const result=await api('/api/repository/worktrees',{method:'POST',body:{projectId:activeProject()?.id,agentId:el.dataset.agent}});toast(`${result.branch} worktree를 준비했습니다.`);await navigate('workspace');}catch(error){toast(error.message);el.disabled=false;}});
  $$('.cli-card[data-capability]').forEach(el=>el.onclick=()=>{selectedCapability=el.dataset.capability;render();});
  $('#add-adapter')?.addEventListener('click',()=>openAdapterProfile());
  $('#edit-adapter')?.addEventListener('click',()=>openAdapterProfile(selectedCapability));
  $('#delete-adapter')?.addEventListener('click',async()=>{if(!confirm('이 커스텀 CLI 프로필을 삭제할까요?'))return;try{await api('/api/adapters/'+encodeURIComponent(selectedCapability),{method:'DELETE'});selectedCapability='';await load();}catch(error){toast(error.message);}});
  $('#create-github-issue')?.addEventListener('click',openGithubIssue);
  if(page==='github'&&state.github?.projectError&&$('.project-board-list .empty'))$('.project-board-list .empty').innerHTML=`<b>Projects 권한이 필요합니다.</b><small>${esc(state.github.projectError)}</small>`;
  $$('.import-issue').forEach(el=>el.onclick=async()=>{const project=activeProject();try{await api('/api/github/import',{method:'POST',body:{projectId:project?.id,issueNumber:el.dataset.number,agentId:project?.masterAgentId||project?.agentIds?.[0]}});toast(`Issue #${el.dataset.number}를 작업으로 가져왔습니다.`);await load();navigate('board');}catch(error){toast(error.message);}});
  if ($('#usage-repo')?.options[0]?.value === '') $('#usage-repo').options[0].remove();
  $('#usage-repo')?.addEventListener('change',async(e)=>{await api('/api/settings',{method:'PUT',body:{activeProjectId:e.target.value}});await load();});
  $('#pick-default-folder')?.addEventListener('click',async()=>{try{const result=await api('/api/pick-folder',{method:'POST'});if(result.path)$('#set-workdir').value=result.path;}catch(e){toast(e.message);}});
  if($('#toggle-autostart'))loadDesktopSettings();
}

async function loadDesktopSettings(){const btn=$('#toggle-autostart');if(!btn)return;try{let current=await api('/api/desktop');if(!current.supported){btn.textContent='브라우저 모드에서는 자동 시작을 설정할 수 없습니다';return;}const paint=()=>{btn.disabled=false;btn.textContent=current.autostart?'✓ Windows 시작 시 자동 실행':'Windows 자동 시작 켜기';};paint();btn.onclick=async()=>{current=await api('/api/desktop/autostart',{method:'POST',body:{on:!current.autostart}});paint();toast(current.autostart?'자동 시작을 켰습니다.':'자동 시작을 껐습니다.');};}catch(e){btn.textContent=e.message;}}

function openGithubIssue(){const project=activeProject();if(!project)return;showModal('GITHUB ISSUE','새 Issue 만들기',`<div class="field"><label>제목</label><input id="gh-title" required placeholder="작업 목표를 한 줄로 적으세요"></div><div class="field"><label>본문</label><textarea id="gh-body" placeholder="배경, 범위, 완료 조건"></textarea></div><label class="check-row"><input id="gh-card" type="checkbox" checked> 마스터 에이전트 작업 카드도 함께 만들기</label><div class="actions"><button class="primary" type="submit">Issue 생성</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{try{const issue=await api('/api/github/issues',{method:'POST',body:{projectId:project.id,title:$('#gh-title').value,body:$('#gh-body').value}});if($('#gh-card').checked){await api('/api/github/import',{method:'POST',body:{projectId:project.id,issueNumber:issue.number,agentId:project.masterAgentId||project.agentIds?.[0]}});}$('#modal').close();toast(`Issue #${issue.number}를 생성했습니다.`);workspaceTab='issues';page='workspace';await load();}catch(error){toast(error.message);}});}

function openProject(id=''){
  const p=projectOf(id)||{name:'',path:'',description:'',agentIds:[],masterAgentId:'',pipeline:[],executionMode:'shared-serial',routingMode:'adaptive',workflowId:'auto'};
  const gitReady=Boolean(id&&state.repository?.git);
  showModal('LOCAL OFFICE',id?'Office 기본 설정':'Office 추가',`
    <div class="prompt-guide"><b>Office = 하나의 로컬 작업 폴더</b><span>Git은 선택 사항입니다. 폴더만으로 시작한 뒤 나중에 Git을 연결해도 팀과 작업 기록은 그대로 유지됩니다.</span></div>
    <div class="row">
      <div class="field"><label>Office 이름</label><input id="project-name" value="${esc(p.name)}" placeholder="my-vibe-office"></div>
      <div class="field"><label>충돌 방지 방식</label><select id="project-mode"><option value="shared-serial" ${p.executionMode!=='isolated-worktrees'?'selected':''}>동일 폴더 쓰기 직렬 보호</option><option value="isolated-worktrees" ${p.executionMode==='isolated-worktrees'?'selected':''} ${gitReady?'':'disabled'}>에이전트별 Git worktree</option></select><span class="hint">worktree는 Git이 연결된 Office에서만 선택할 수 있습니다.</span></div>
    </div>
    <div class="field"><label>로컬 작업 폴더</label><div class="input-action"><input id="project-path" value="${esc(p.path)}" placeholder="C:\\workspace\\my-app"><button type="button" class="secondary" id="pick-project-folder">찾기</button></div></div>
    <div class="field"><label>Office 공통 지시</label><textarea id="project-description" placeholder="프로젝트 용도, 금지 사항, 코드 규칙, 공통 완료 기준">${esc(p.description)}</textarea><span class="hint">모든 팀과 직원의 실행 프롬프트에 공통으로 결합됩니다.</span></div>
    <div class="field"><label>Office 직원 풀</label><div class="agent-check-grid">${state.agents.map(a=>`<label><input type="checkbox" name="project-agent" value="${a.id}" ${p.agentIds.includes(a.id)?'checked':''}><i style="background:${a.color}"></i>${esc(a.name)} <small>${esc(a.modeId||a.role||a.adapter)}</small></label>`).join('')||'<span class="hint">먼저 에이전트를 생성하세요.</span>'}</div><span class="hint">팀에 배치된 직원을 풀에서 제거하려면 먼저 팀 설정에서 제외하세요.</span></div>
    <div class="actions"><button class="primary" type="submit">Office 설정 저장</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{
      const agentIds=$$('input[name="project-agent"]:checked').map(el=>el.value);
      const saved=await api('/api/projects',{method:'POST',body:{id,name:$('#project-name').value,path:$('#project-path').value,description:$('#project-description').value,executionMode:$('#project-mode').value,agentIds,masterAgentId:p.masterAgentId,pipeline:p.pipeline,routingMode:p.routingMode,workflowId:p.workflowId}});
      await api('/api/settings',{method:'PUT',body:{activeProjectId:saved.id}});$('#modal').close();await load();
    });
  $('#pick-project-folder').onclick=async()=>{try{const result=await api('/api/pick-folder',{method:'POST'});if(result.path){$('#project-path').value=result.path;if(!$('#project-name').value.trim())$('#project-name').value=result.path.split(/[\\/]/).filter(Boolean).at(-1)||'';}}catch(e){toast(e.message);}};
}

function openTeamManager(){
  const project=activeProject();if(!project)return;
  const rows=(project.teams||[]).map(team=>`<article class="team-manager-row"><div><span class="role-badge assigned">${esc(routingLabel(team))}</span><b>${esc(team.name)}</b><small>리드 ${esc(agentOf(team.leadAgentId)?.name||'미지정')} · 직원 ${team.agentIds.length}명 · ${esc(workflowOf(team.workflowId)?.name||'자동')}</small><p>${esc(team.instructions||team.description||'팀 운영 지시가 없습니다.')}</p></div><div class="actions"><button type="button" class="secondary edit-team" data-id="${team.id}">편집</button><button type="button" class="danger delete-team" data-id="${team.id}">삭제</button></div></article>`).join('');
  showModal('OFFICE ORGANIZATION','팀·리드·워크플로 관리',`<div class="prompt-guide"><b>여러 마스터, 독립된 팀 운영</b><span>각 팀은 리드, 직원, 팀 지시, 라우팅 방식, 기본 워크플로를 독립적으로 가집니다. 작업은 선택한 팀 안에서만 배분됩니다.</span></div><div class="team-manager-list">${rows||'<div class="empty">아직 팀이 없습니다.</div>'}</div><div class="actions"><button type="button" class="primary add-team">＋ 팀 만들기</button><button class="secondary" value="cancel">닫기</button></div>`,null);
  $('.add-team').onclick=()=>{$('#modal').close();openTeamEditor();};
  $$('.edit-team').forEach(el=>el.onclick=()=>{$('#modal').close();openTeamEditor(el.dataset.id);});
  $$('.delete-team').forEach(el=>el.onclick=async()=>{if(!confirm('이 팀 설정을 삭제할까요? 작업 기록과 직원은 삭제되지 않습니다.'))return;await api(`/api/projects/${project.id}/teams/${el.dataset.id}`,{method:'DELETE'});$('#modal').close();await load();openTeamManager();});
}

function openTeamEditor(teamId=''){
  const project=activeProject();if(!project)return;
  const employees=projectAgents(project);if(!employees.length){toast('먼저 Office 직원 풀에 에이전트를 배치하세요.');openProject(project.id);return;}
  const team=(project.teams||[]).find(item=>item.id===teamId)||{name:'',description:'',instructions:'',leadAgentId:'',agentIds:[],pipeline:[],routingMode:'adaptive',workflowId:'auto'};
  const initialAgentIds=teamId?team.agentIds:employees.map(agent=>agent.id);
  const workflowOptions=(state.presets.workflows||[]).map(w=>`<option value="${w.id}" ${team.workflowId===w.id?'selected':''}>${esc(w.name)} · ${esc(w.description)}</option>`).join('');
  showModal('TEAM CONFIGURATION',teamId?'팀 설정 편집':'새 팀 만들기',`<div class="row"><div class="field"><label>팀 이름</label><input id="team-name" value="${esc(team.name)}" required placeholder="콘텐츠 운영팀"></div><div class="field"><label>팀 리드 / 마스터</label><select id="team-lead" required><option value="">리드를 선택하세요</option>${employees.map(a=>`<option value="${a.id}" ${team.leadAgentId===a.id?'selected':''}>${esc(a.name)} · ${esc(presetOf(a.presetId)?.name||a.role||a.modeId)}</option>`).join('')}</select></div></div><div class="field"><label>팀 설명</label><input id="team-description" value="${esc(team.description)}" placeholder="이 팀이 맡는 영역과 완료 책임"></div><div class="field team-roster-field"><div class="team-roster-head"><div><label>팀 직원</label><span id="team-selected-count">${initialAgentIds.length}명 선택</span></div><div class="actions"><button type="button" class="secondary" id="team-select-all">전체 선택</button><button type="button" class="secondary" id="team-clear-all">선택 해제</button></div></div><div class="team-agent-grid">${employees.map(a=>{const preset=presetOf(a.presetId);return `<label class="team-agent-option"><input type="checkbox" name="team-agent" value="${a.id}" ${initialAgentIds.includes(a.id)?'checked':''}><span class="team-agent-avatar" style="--agent-color:${a.color}">${esc(a.name.slice(0,2))}</span><span class="team-agent-copy"><b>${esc(a.name)}</b><small>${esc(preset?.name||a.role||'사용자 역할')}</small></span><em>${esc(a.modeId||preset?.modeId||a.adapter)}</em><span class="team-agent-check">✓</span></label>`;}).join('')}</div><span class="hint">새 팀은 Office 직원 전체를 기본 선택합니다. 필요 없는 직원만 제외하세요.</span></div><div class="field"><label>팀 운영 지시</label><textarea id="team-instructions" placeholder="이 팀만의 우선순위, 작업 원칙, 리뷰 기준, 인계 형식">${esc(team.instructions)}</textarea><span class="hint">역할 프리셋·개인 지시·Office 규칙과 함께 실행 시점에 결합됩니다.</span></div><div class="row"><div class="field"><label>라우팅 방식</label><select id="team-routing"><option value="adaptive" ${team.routingMode==='adaptive'?'selected':''}>요청에 맞는 직원 자동 선택</option><option value="manual" ${team.routingMode==='manual'?'selected':''}>리드가 직접 처리</option><option value="sequential" ${team.routingMode==='sequential'?'selected':''}>아래 순서대로 실행</option></select></div><div class="field"><label>기본 워크플로</label><select id="team-workflow">${workflowOptions}</select></div></div><div class="field"><div class="team-pipeline-head"><label id="team-pipeline-label">실행 우선순위</label><span>화살표로 순서를 바꾸세요</span></div><div id="team-pipeline" class="team-pipeline-list"></div><span class="hint">자동 라우팅에서는 후보 우선순위, 순차 라우팅에서는 실제 실행 순서입니다.</span></div><div class="actions team-editor-actions"><button class="primary" type="submit">팀 저장</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{const leadAgentId=$('#team-lead').value,agentIds=$$('input[name="team-agent"]:checked').map(el=>el.value),pipeline=$$('#team-pipeline [data-agent-id]').map(el=>el.dataset.agentId);await api(`/api/projects/${project.id}/teams`,{method:'POST',body:{id:teamId,name:$('#team-name').value,description:$('#team-description').value,instructions:$('#team-instructions').value,leadAgentId,agentIds,pipeline,routingMode:$('#team-routing').value,workflowId:$('#team-workflow').value}});$('#modal').close();await load();toast(teamId?'팀 설정을 저장했습니다.':'팀을 만들었습니다.');});
  let pipelineOrder=[...new Set([...(team.pipeline||[]),...employees.map(agent=>agent.id)])];
  const selectedIds=()=>$$('input[name="team-agent"]:checked').map(input=>input.value);
  const renderPipeline=()=>{const selected=new Set(selectedIds()),ordered=pipelineOrder.filter(id=>selected.has(id));for(const id of selected)if(!ordered.includes(id))ordered.push(id);pipelineOrder=[...ordered,...pipelineOrder.filter(id=>!selected.has(id))];$('#team-selected-count').textContent=`${selected.size}명 선택`;$('#team-pipeline-label').textContent=$('#team-routing').value==='sequential'?'순차 실행 순서':'실행 우선순위';$('#team-pipeline').innerHTML=ordered.map((id,index)=>{const agent=agentOf(id),preset=presetOf(agent?.presetId);return `<div data-agent-id="${id}"><strong>${index+1}</strong><i style="background:${agent?.color||'#777'}"></i><span><b>${esc(agent?.name||id)}</b><small>${esc(preset?.name||agent?.role||agent?.modeId||'')}</small></span><div><button type="button" class="pipeline-up" aria-label="${esc(agent?.name||'직원')} 위로" ${index===0?'disabled':''}>↑</button><button type="button" class="pipeline-down" aria-label="${esc(agent?.name||'직원')} 아래로" ${index===ordered.length-1?'disabled':''}>↓</button></div></div>`;}).join('')||'<div class="empty compact">팀 직원을 한 명 이상 선택하세요.</div>';$$('.pipeline-up').forEach((button,index)=>button.onclick=()=>{[pipelineOrder[index-1],pipelineOrder[index]]=[pipelineOrder[index],pipelineOrder[index-1]];renderPipeline();});$$('.pipeline-down').forEach((button,index)=>button.onclick=()=>{[pipelineOrder[index+1],pipelineOrder[index]]=[pipelineOrder[index],pipelineOrder[index+1]];renderPipeline();});};
  $$('input[name="team-agent"]').forEach(input=>input.onchange=renderPipeline);
  $('#team-select-all').onclick=()=>{$$('input[name="team-agent"]').forEach(input=>input.checked=true);renderPipeline();};
  $('#team-clear-all').onclick=()=>{const lead=$('#team-lead').value;$$('input[name="team-agent"]').forEach(input=>input.checked=input.value===lead);renderPipeline();};
  $('#team-lead').onchange=()=>{const id=$('#team-lead').value,box=id&&$(`input[name="team-agent"][value="${CSS.escape(id)}"]`);if(box)box.checked=true;if(id&&!pipelineOrder.includes(id))pipelineOrder.unshift(id);renderPipeline();};
  $('#team-routing').onchange=renderPipeline;renderPipeline();
}

function openSchedule(){if(!state.agents.length){toast('먼저 에이전트를 만들어 주세요.');navigate('agents');return;}const next=new Date(Date.now()+3600000);next.setSeconds(0,0);const local=new Date(next.getTime()-next.getTimezoneOffset()*60000).toISOString().slice(0,16);const projects=state.settings.projects||[];showModal('AUTOMATION','예약 작업 만들기',`<div class="field"><label>이름</label><input id="sch-name" placeholder="매일 프로젝트 상태 점검"></div><div class="row"><div class="field"><label>에이전트</label><select id="sch-agent">${state.agents.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label>방식</label><select id="sch-type"><option value="once">한 번</option><option value="interval">반복 간격</option><option value="daily">매일</option><option value="weekly">매주</option></select></div></div><div class="row"><div class="field"><label>1회 실행 시각</label><input id="sch-at" type="datetime-local" value="${local}"></div><div class="field"><label>반복 간격(분)</label><input id="sch-interval" type="number" min="1" value="60"></div></div><div class="row"><div class="field"><label>매일/매주 시각</label><input id="sch-time" type="time" value="09:00"></div><div class="field"><label>요일</label><select id="sch-weekday">${['일','월','화','수','목','금','토'].map((d,i)=>`<option value="${i}" ${i===1?'selected':''}>${d}요일</option>`).join('')}</select></div></div><div class="field"><label>프로젝트</label><select id="sch-project"><option value="">기본 작업 폴더</option>${projects.map(p=>`<option value="${esc(p.path)}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>작업 폴더</label><input id="sch-workdir" value="${esc(state.settings.defaultWorkdir||'')}"></div><div class="field"><label>작업 지시</label><textarea id="sch-prompt" placeholder="정기적으로 수행할 작업과 완료 조건"></textarea></div><div class="actions"><button class="primary" type="submit">예약 저장</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{await api('/api/schedules',{method:'POST',body:{name:$('#sch-name').value,agentId:$('#sch-agent').value,type:$('#sch-type').value,runAt:new Date($('#sch-at').value).toISOString(),intervalMinutes:$('#sch-interval').value,time:$('#sch-time').value,weekday:$('#sch-weekday').value,workdir:$('#sch-workdir').value,prompt:$('#sch-prompt').value}});$('#modal').close();await load();});$('#sch-project').onchange=()=>{if($('#sch-project').value)$('#sch-workdir').value=$('#sch-project').value;};}

function showModal(kicker,title,html,onSubmit) {
  delete $('#modal').dataset.cardId;delete $('#modal').dataset.cardStatus;
  $('#modal-kicker').textContent=kicker; $('#modal-title').textContent=title; $('#modal-body').innerHTML=html;
  const form=$('#modal-form'); form.onsubmit=async(e)=>{e.preventDefault();if(e.submitter?.value==='cancel'){$('#modal').close();return;}await onSubmit?.(e);};
  $$('[value="cancel"]',$('#modal-body')).forEach(button=>{button.type='button';button.onclick=()=>$('#modal').close();});
  $('#modal').showModal();
}

